using FieldRole=v3::FieldRole;using TrialFrame=v3::TrialFrame;using PrecisionPath=v3::PrecisionPath;using v3::precision_path;using FieldSample=v3::FieldSample;
using HeldTemperature=v3::HeldTemperature;using PatchBinding=v3::PatchBinding;using Exposure=v3::Exposure;using v3::exposure_key;
